'use strict'

const http2 = require('node:http2')
const Fastify = require('/tmp/cxbench-damage/2bf4265b99-hooks')

const BIG = Buffer.alloc(64 * 1024 * 1024, 0x61)

async function main () {
  const fastify = Fastify({ http2: true, logger: false })

  fastify.get('/big', (req, reply) => {
    reply.header('content-type', 'application/octet-stream').send(BIG)
  })
  fastify.get('/small', (req, reply) => {
    reply.send({ ok: true })
  })

  await fastify.listen({ port: 0 })
  const port = fastify.server.address().port
  const session = http2.connect(`http://localhost:${port}`)
  session.on('error', (e) => console.log('SESSION ERROR:', e.code, e.message))

  // 1. Request the large payload, then cancel it as soon as headers arrive.
  await new Promise((resolve) => {
    const req = session.request({ ':path': '/big' })
    req.on('response', () => {
      req.close(http2.constants.NGHTTP2_CANCEL)
      resolve()
    })
    req.on('error', (e) => console.log('big req error:', e.code))
    req.resume()
    req.end()
  })

  console.log('cancelled the large reply; now issuing a follow-up request')

  // 2. Reuse the same session. If it was poisoned, this never completes.
  const result = await new Promise((resolve) => {
    const timer = setTimeout(() => resolve('TIMEOUT — session poisoned'), 5000)
    const req = session.request({ ':path': '/small' })
    let body = ''
    req.setEncoding('utf8')
    req.on('data', (c) => { body += c })
    req.on('end', () => { clearTimeout(timer); resolve('OK: ' + body) })
    req.on('error', (e) => { clearTimeout(timer); resolve('ERROR: ' + e.code) })
    req.end()
  })

  console.log('follow-up result:', result)
  console.log('session destroyed?', session.destroyed)
  console.log('rss after:', Math.round(process.memoryUsage().rss / 1024 / 1024), 'MB')

  session.destroy()
  await fastify.close()
  process.exit(result.startsWith('OK') ? 0 : 1)
}

main().catch((e) => { console.error('FATAL', e); process.exit(2) })

